// CPU-only full saved-artifact replay. No source GPU/reference solver called.
#include <iostream>
#include <iomanip>
#include <stdexcept>
#include <cstring>
#include "independent_oracle.h"
struct Case{unsigned n,z;std::vector<unsigned>ptr,rows,diag;std::vector<float>initial;std::string matrix;};
static size_t offset=0;
template<class T>std::vector<T>take(const std::vector<double>&v,size_t n){if(offset+n>v.size())throw std::runtime_error("shortartifact");std::vector<T>out(n);for(size_t i=0;i<n;i++){double x=v[offset++];if(!std::isfinite(x))throw std::runtime_error("nonfiniteinput");out[i]=T(x);if(double(out[i])!=x)throw std::runtime_error("lossyinputdecode");}return out;}
int main(int argc,char**argv){if(argc!=3){std::cerr<<"usage: replay_full_state ARTIFACT_F64 CASES_TSV\n";return 2;}std::ifstream f(argv[1],std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("missingartifact");auto bytes=f.tellg();if(bytes<0||size_t(bytes)%8)throw std::runtime_error("artifactsize");std::vector<double>v(size_t(bytes)/8);f.seekg(0);f.read((char*)v.data(),bytes);if(!f)throw std::runtime_error("shortread");std::ifstream spec(argv[2]);if(!spec)throw std::runtime_error("missingcases");std::vector<Case>cases;std::string line;while(std::getline(spec,line)){size_t a=line.find('\t'),b=line.find('\t',a+1);if(a==line.npos||b==line.npos)throw std::runtime_error("badcase");Case c;auto h=take<double>(v,7);if(h[0]!=cases.size())throw std::runtime_error("caseid");c.n=unsigned(h[1]);c.z=unsigned(h[2]);if(!c.n||!c.z||h[1]!=c.n||h[2]!=c.z||h[6]!=10353)throw std::runtime_error("header");c.ptr=take<unsigned>(v,c.n+1);c.rows=take<unsigned>(v,c.z);c.initial=take<float>(v,c.z);c.diag=take<unsigned>(v,c.n);take<unsigned>(v,c.n+1);take<unsigned>(v,c.z);take<unsigned>(v,c.n);take<int>(v,c.n);c.matrix=line.substr(b+1);cases.push_back(std::move(c));}if(cases.size()!=4)throw std::runtime_error("casescount");bool pass=true;std::cout<<std::setprecision(17)<<"{\"input_prefix_count\":"<<offset<<",\"cases\":[";for(size_t i=0;i<cases.size();i++){auto&c=cases[i];auto lu=take<float>(v,c.z),x=take<float>(v,c.n);auto r=independent_lu(c.ptr,c.rows,c.diag,c.initial,lu,x,c.matrix);pass &=r.pass;if(i)std::cout<<",";std::cout<<"{\"case\":"<<i<<",\"pass\":"<<(r.pass?"true":"false")<<",\"componentwise_backward_error\":"<<r.componentwise<<",\"normwise_backward_error\":"<<r.normwise<<",\"original_system_backward_error\":"<<r.solve_backward<<",\"product_terms\":"<<r.product_terms<<"}";}if(offset!=v.size())throw std::runtime_error("trailingartifact");std::cout<<"],\"checked_values\":"<<v.size()<<",\"pass\":"<<(pass?"true":"false")<<"}\n";return pass?0:8;}
